<?php require 'includes/config.php';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';$qty=max(1,min(999,(int)($_POST['qty']??1)));$s=db()->prepare('SELECT stock FROM products WHERE id=? AND active=1');$s->execute([$id]);$stock=$s->fetchColumn();if($action==='remove')unset($_SESSION['cart'][$id]);elseif($stock!==false){if($action==='add')$_SESSION['cart'][$id]=min((int)$stock,($_SESSION['cart'][$id]??0)+$qty);if($action==='update')$_SESSION['cart'][$id]=min((int)$stock,$qty);if(empty($_SESSION['cart'][$id]))unset($_SESSION['cart'][$id]);}redirect('cart.php');}$pageTitle='Your Cart';require 'includes/header.php';$rows=cart_rows();?><section class="container section-space"><div class="eyebrow">YOUR SELECTION</div><h1 class="page-title">Shopping <em>Bag</em></h1><?php if(!$rows):?><div class="empty-state"><i class="bi bi-bag"></i><h3>Your bag is empty</h3><p>Discover something wonderful.</p><a class="btn btn-gold" href="shop.php">START SHOPPING</a></div><?php else:?><div class="row g-4 mt-3"><div class="col-lg-8"><?php foreach($rows as $r):?><div class="cart-row"><img src="<?=e($r['image'])?>" alt=""><div class="flex-grow-1"><h5><?=e($r['name'])?></h5><p class="text-gold"><?=money($r['price'])?></p><form method="post" class="d-inline-flex gap-2"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="update"><input class="form-control qty-input" type="number" min="1" max="<?=$r['stock']?>" name="qty" value="<?=$r['qty']?>"><button class="btn btn-outline-gold">Update</button></form><form method="post" class="d-inline-block ms-2"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="remove"><button class="btn btn-link text-danger">Remove</button></form></div><strong><?=money($r['price']*$r['qty'])?></strong></div><?php endforeach;?></div><div class="col-lg-4"><div class="filter-panel"><h4>Order Summary</h4><div class="d-flex justify-content-between mt-4"><span>Subtotal</span><b><?=money(cart_total())?></b></div><p class="muted small mt-3">Delivery is calculated during checkout.</p><hr><a href="checkout.php" class="btn btn-gold w-100">PROCEED TO CHECKOUT →</a></div></div></div><?php endif;?></section><?php require 'includes/footer.php';?>